try:
    print('>>> f = hasattr')
    print('>>> x = 3')
    print('>>> y = slice(0)')
    print('>>> f(x, y)')
    f = hasattr
    x = 3
    y = slice(0)
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
